:root {
    /* Značkové farby (RGB triplety kvôli priehľadnosti) */
    --color-navy-rgb: 44, 62, 80;
    --color-navy-dark-rgb: 20, 28, 38;
    --color-navy-hover: #1c2833;
    --color-accent-rgb: 241, 196, 15;
    --color-blue-rgb: 52, 152, 219;
    --color-amber: #e3a51a;
    --color-amber-light: #fbe8c2;
    --color-teal: #16a085;
    --color-white-rgb: 255, 255, 255;
    --color-shadow-rgb: 0, 0, 0;

    /* Text */
    --color-text: #333;
    --color-text-muted: #555;

    /* Pozadia a okraje */
    --color-bg: #f2f2f2;
    --color-bg-soft: #fafafa;
    --color-gray: #999;
    --color-gray-light: #ccc;
    --color-gray-pale: #e0e0e0;
}

/* Základné nastavenia */
html, body {
    height: 100%;
}

html {
    scrollbar-gutter: stable;
}

body {
    font-family: Arial, sans-serif;
    margin: 0;
    background-color: var(--color-bg);
    background-image:
        radial-gradient(circle at 8% -10%, rgba(var(--color-accent-rgb), 0.22), transparent 45%),
        radial-gradient(circle at 92% 15%, rgba(var(--color-blue-rgb), 0.16), transparent 42%),
        radial-gradient(circle at 85% 105%, rgba(var(--color-navy-rgb), 0.18), transparent 45%);
    background-attachment: fixed;
    color: var(--color-text);
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

main {
    flex: 1;
}

/* Hlavička */
header {
    position: sticky;
    top: 0;
    z-index: 10;
    background: rgba(var(--color-navy-dark-rgb), 0.85);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border-bottom: 1px solid rgba(var(--color-white-rgb), 0.2);
    color: white;
    padding: 16px 30px;
    box-shadow: 0 4px 20px rgba(var(--color-shadow-rgb), 0.12);
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
}

/* Logo + názov */
.brand {
    display: flex;
    align-items: center;
    gap: 12px;
    color: white;
    text-decoration: none;
}

.logo-placeholder {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(var(--color-white-rgb), 0.15);
    border: 1px solid rgba(var(--color-white-rgb), 0.3);
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: Arial, sans-serif;
    font-weight: 700;
    font-size: 18px;
    flex-shrink: 0;
}

.brand-name {
    font-family: Arial, sans-serif;
    font-weight: 700;
    font-size: 22px;
    letter-spacing: 0.5px;
}

/* Menu */
nav {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
}

nav a {
    color: white;
    text-decoration: none;
    padding: 6px 14px;
    font-size: 16px;
    border-radius: 999px;
    transition: background-color 0.2s ease, color 0.2s ease;
}

nav a:hover {
    background-color: rgba(var(--color-white-rgb), 0.15);
    color: rgb(var(--color-accent-rgb));
}

nav a.active {
    background-color: rgba(var(--color-white-rgb), 0.2);
    color: rgb(var(--color-accent-rgb));
}

/* Hlavný obsah */
main {
    max-width: 800px;
    margin: 30px auto;
    background-color: rgba(var(--color-white-rgb), 0.75);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    padding: 20px;
    border-radius: 12px;
    border: 1px solid rgba(var(--color-white-rgb), 0.5);
    box-shadow: 0 8px 30px rgba(var(--color-shadow-rgb), 0.08);
}

/* Karty v obsahu */
.card {
    background-color: rgba(var(--color-white-rgb), 0.55);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(var(--color-white-rgb), 0.6);
    border-radius: 14px;
    padding: 20px;
    margin-bottom: 20px;
    box-shadow: 0 4px 16px rgba(var(--color-shadow-rgb), 0.06);
}

.card h3 {
    margin-top: 0;
}

/* Trello board */
/* Stránka Vývoj: široký obsah, Trello vľavo a história vpravo */
main.siroke {
    width: min(1400px, calc(100% - 40px));
    max-width: none;
    box-sizing: border-box;
}

main.siroke .hero {
    margin: 0 auto 10px;
    padding: 10px;
}

main.siroke .hero .uvod-podtitul {
    margin-bottom: 0;
}

.vyvoj-rozlozenie {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(300px, 380px);
    gap: 20px;
    align-items: start;
}

.trello-board {
    display: flex;
    gap: 14px;
    align-items: flex-start;
    overflow-x: auto;
    padding-bottom: 10px;
}

.trello-stlpec {
    flex: 0 0 270px;
    display: flex;
    flex-direction: column;
    max-height: 68vh;
    background-color: rgba(var(--color-navy-rgb), 0.05);
    border: 1px solid rgba(var(--color-navy-rgb), 0.1);
    border-radius: 12px;
    padding: 14px;
    box-sizing: border-box;
}

.trello-stlpec h4 {
    margin: 0 0 10px;
    font-size: 14px;
    line-height: 1.4;
}

.trello-zoznam {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 0;
    margin: 0;
    overflow-y: auto;
}

.trello-zoznam li {
    background-color: rgba(var(--color-white-rgb), 0.8);
    border: 1px solid rgba(var(--color-navy-rgb), 0.08);
    border-radius: 8px;
    padding: 8px 10px;
    font-size: 13px;
    line-height: 1.4;
}

.trello-termin {
    display: block;
    width: fit-content;
    margin-top: 6px;
    padding: 2px 8px;
    border-radius: 999px;
    background-color: var(--color-amber-light);
    color: rgb(var(--color-navy-rgb));
    font-size: 11px;
    font-weight: 700;
}

.trello-pocet {
    display: block;
    margin-top: 2px;
    font-size: 11px;
    font-weight: 400;
    color: var(--color-text-muted);
}

.trello-zoznam li.hotovo {
    background-color: rgba(var(--color-white-rgb), 0.45);
}

.trello-zoznam li.hotovo .trello-nazov {
    text-decoration: line-through;
    color: var(--color-text-muted);
}

.trello-termin.hotovo {
    background-color: var(--color-teal);
    color: white;
}

.trello-termin.hotovo::before {
    content: "✓ ";
}

.trello-checklist {
    display: block;
    margin-top: 6px;
    font-size: 11px;
    color: var(--color-text-muted);
}

.trello-info {
    margin: 0 0 14px;
    font-size: 14px;
    color: var(--color-text-muted);
}

/* História zmien */
.git-historia {
    max-height: 68vh;
    overflow-y: auto;
    padding-right: 4px;
}

.git-den {
    margin: 18px 0 8px;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--color-text-muted);
}

.git-den:first-child {
    margin-top: 0;
}

.git-zoznam {
    position: relative;
    list-style: none;
    margin: 0;
    padding: 0;
}

/* zvislá čiara, na ktorej sedia avatary */
.git-zoznam::before {
    content: "";
    position: absolute;
    top: 16px;
    bottom: 16px;
    left: 15px;
    width: 2px;
    background-color: rgba(var(--color-navy-rgb), 0.15);
}

.git-zoznam li {
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 8px 0;
}

.git-avatar {
    flex-shrink: 0;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    border: 2px solid white;
    box-shadow: 0 1px 4px rgba(var(--color-shadow-rgb), 0.2);
    background-color: rgb(var(--color-navy-rgb));
}

.git-iniciala {
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    color: white;
    font-size: 14px;
    font-weight: 700;
}

.git-telo {
    flex: 1;
    min-width: 0;
}

.git-sprava {
    display: block;
    font-size: 14px;
    line-height: 1.4;
    overflow-wrap: anywhere;
}

.git-meta {
    display: block;
    margin-top: 2px;
    font-size: 12px;
    color: var(--color-text-muted);
}

.git-sha {
    flex-shrink: 0;
    margin-top: 2px;
    font-family: "Courier New", monospace;
    font-size: 11px;
    padding: 2px 7px;
    border-radius: 6px;
    background-color: rgba(var(--color-navy-rgb), 0.08);
    color: rgb(var(--color-navy-rgb));
    text-decoration: none;
}

.git-sha:hover {
    background-color: rgb(var(--color-navy-rgb));
    color: rgb(var(--color-accent-rgb));
}

/* Zápisnice */
.zapisnica {
    border: 1px solid rgba(var(--color-navy-rgb), 0.12);
    border-radius: 12px;
    background-color: rgba(var(--color-white-rgb), 0.6);
    margin-bottom: 10px;
}

.zapisnica summary {
    cursor: pointer;
    padding: 14px 16px;
    font-weight: 700;
    list-style: none;
}

.zapisnica summary::-webkit-details-marker {
    display: none;
}

.zapisnica summary::before {
    content: "+";
    display: inline-block;
    width: 22px;
    color: var(--color-amber);
}

.zapisnica[open] summary::before {
    content: "−";
}

.zapisnica-telo {
    padding: 0 16px 16px;
    font-size: 14px;
    line-height: 1.6;
}

.zapisnica-telo h4 {
    margin: 16px 0 6px;
}

.zapisnica-telo ol,
.zapisnica-telo ul {
    margin: 0;
    padding-left: 20px;
}

.zapisnica-telo .tabulka-wrap {
    margin-top: 6px;
}

/* Tabuľky */
.tabulka-wrap {
    width: 100%;
    overflow-x: auto;
}

table {
    border-collapse: collapse;
    width: 100%;
    min-width: 420px;
    font-size: 13px;
}

th, td {
    border: 1px solid var(--color-gray-pale);
    padding: 8px 10px;
    text-align: left;
    vertical-align: top;
}

th {
    background-color: rgb(var(--color-navy-rgb));
    color: white;
}

/* Úvodná stránka */
.hero {
    margin: 20px auto;
    padding: 20px 30px;
    text-align: center;
    animation: hero-fade-in 0.6s ease-out;
}

.hero h2 {
    font-size: 26px;
    line-height: 1.3;
    margin-bottom: 14px;
}

.hero p {
    font-size: 14px;
    line-height: 1.7;
}

.uvod-podtitul {
    font-size: 18px;
    color: var(--color-text-muted);
    margin-bottom: 24px;
}

.features {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
    list-style: none;
    padding: 0;
    margin: 0;
    text-align: center;
}

.features li {
    background-color: rgba(var(--color-white-rgb), 0.55);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(var(--color-white-rgb), 0.6);
    border-radius: 14px;
    padding: 16px;
    box-shadow: 0 4px 16px rgba(var(--color-shadow-rgb), 0.06);
}

.features-icon {
    display: block;
    font-size: 22px;
    margin-bottom: 8px;
}

.features h4 {
    margin: 0 0 6px;
    font-size: 15px;
}

.features p {
    margin: 0;
    font-size: 13px;
    color: var(--color-text-muted);
    line-height: 1.5;
}

@keyframes hero-fade-in {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Stránka Dokumenty: PDF vedľa seba */
.dokumenty-rozlozenie {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
}

.dokumenty-rozlozenie .card {
    margin-bottom: 0;
}

.pdf-card {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.pdf-nahlad {
    display: block;
    width: 100%;
    height: calc(100vh - 260px);
    min-height: 500px;
    border: 1px solid var(--color-gray-light);
    border-radius: 8px;
    margin-bottom: 14px;
}

.pdf-tlacidlo {
    display: inline-block;
    background-color: rgb(var(--color-navy-rgb));
    color: white;
    text-decoration: none;
    padding: 10px 20px;
    border-radius: 8px;
    font-size: 14px;
    transition: background-color 0.2s ease;
}

.pdf-tlacidlo:hover {
    background-color: var(--color-navy-hover);
}

@media (max-width: 600px) {
    .pdf-nahlad {
        display: none;
    }

    .pdf-tlacidlo {
        display: block;
        text-align: center;
    }
}

/* Členovia tímu */
.tim-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 15px;
}

.clen {
    display: flex;
    align-items: center;
    gap: 20px;
    border: 1px solid var(--color-gray-light);
    border-radius: 8px;
    padding: 15px 20px;
    background-color: var(--color-bg-soft);
}

.clen-info {
    flex: 1;
}

.clen h3 {
    margin-top: 0;
}

.avatar-placeholder {
    width: 90px;
    height: 90px;
    border-radius: 50%;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: 700;
    font-size: 26px;
}

.avatar-1 {
    background-color: rgb(var(--color-navy-rgb));
}

.avatar-2 {
    background-color: var(--color-amber);
}

.avatar-3 {
    background-color: rgb(var(--color-blue-rgb));
}

.avatar-4 {
    background-color: var(--color-teal);
}

/* Pätička */
footer {
    background-color: rgb(var(--color-navy-rgb));
    color: white;
    text-align: center;
    padding: 15px;
    margin-top: 30px;
}

footer nav {
    display: flex;
    justify-content: center;
    flex-wrap: wrap;
    margin: 0 0 8px;
}

footer nav a {
    color: white;
    text-decoration: none;
    margin: 0 12px;
    font-size: 14px;
}

footer nav a:hover {
    color: rgb(var(--color-accent-rgb));
    text-decoration: underline;
}

footer p {
    margin: 0;
    font-size: 13px;
    color: var(--color-gray-light);
}

.foto-tim {
    width: 100%;
    max-width: 100%;
    height: auto;
    border-radius: 8px;
    margin-bottom: 20px;
}

/* Responzívny layout */
@media (max-width: 720px) {
    .vyvoj-rozlozenie {
        grid-template-columns: minmax(0, 1fr);
    }
}

@media (max-width: 1000px) {
    .dokumenty-rozlozenie {
        grid-template-columns: minmax(0, 1fr);
    }
}

@media (max-width: 768px) {
    header {
        flex-direction: column;
        text-align: center;
        padding: 16px;
    }

    nav {
        justify-content: center;
    }

    main {
        max-width: 100%;
        margin: 20px 15px;
        padding: 15px;
    }

    .tim-grid {
        grid-template-columns: 1fr;
    }

    .clen {
        flex-direction: column;
        text-align: center;
    }

    .features {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 480px) {
    .brand-name {
        font-size: 18px;
    }

    .logo-placeholder {
        width: 34px;
        height: 34px;
        font-size: 16px;
    }

    nav a {
        font-size: 14px;
        padding: 5px 10px;
    }

    main {
        margin: 15px 10px;
        padding: 12px;
    }

    .hero {
        padding: 20px 10px;
    }

    .card {
        padding: 14px;
    }


    footer nav a {
        margin: 0 8px;
    }
}

// História zmien sa číta zo súboru commits.json, ktorý pravidelne aktualizuje GitHub Action.
const historia = document.getElementById("git-historia");

function vypisChybuHistorie(sprava) {
    historia.innerHTML = "";
    const p = document.createElement("p");
    p.textContent = sprava;
    historia.appendChild(p);
}

// kľúč dňa, napríklad 2026-10-27, podľa miestneho času
function kluc(datum) {
    return datum.getFullYear() + "-" + datum.getMonth() + "-" + datum.getDate();
}

function nazovDna(datum) {
    const dnes = new Date();
    const vcera = new Date();
    vcera.setDate(vcera.getDate() - 1);

    if (kluc(datum) === kluc(dnes)) {
        return "Dnes";
    }
    if (kluc(datum) === kluc(vcera)) {
        return "Včera";
    }
    return datum.toLocaleDateString("sk-SK", { weekday: "long", day: "numeric", month: "long" });
}

function vytvorCommit(commit) {
    const datum = new Date(commit.datum);
    const li = document.createElement("li");

    if (commit.avatar) {
        const avatar = document.createElement("img");
        avatar.className = "git-avatar";
        avatar.src = commit.avatar + "&s=64";
        avatar.alt = commit.autor;
        avatar.width = 32;
        avatar.height = 32;
        li.appendChild(avatar);
    } else {
        const iniciala = document.createElement("span");
        iniciala.className = "git-avatar git-iniciala";
        iniciala.textContent = commit.autor.charAt(0).toUpperCase();
        li.appendChild(iniciala);
    }

    const telo = document.createElement("div");
    telo.className = "git-telo";

    const sprava = document.createElement("span");
    sprava.className = "git-sprava";
    // pri dlhších správach stačí prvý riadok
    sprava.textContent = commit.sprava.split(String.fromCharCode(10))[0];
    telo.appendChild(sprava);

    const meta = document.createElement("span");
    meta.className = "git-meta";
    const cas = datum.toLocaleTimeString("sk-SK", { hour: "2-digit", minute: "2-digit" });
    meta.textContent = commit.autor + " · " + cas;
    telo.appendChild(meta);
    li.appendChild(telo);

    const kod = document.createElement("a");
    kod.className = "git-sha";
    kod.href = commit.url;
    kod.textContent = commit.sha;
    li.appendChild(kod);

    return li;
}

function nacitajHistoriu() {
    fetch("commits.json", { cache: "no-store" })
        .then(function (odpoved) {
            if (!odpoved.ok) {
                throw new Error("commits.json sa nenašiel");
            }
            return odpoved.json();
        })
        .then(function (commity) {
            historia.innerHTML = "";

            if (commity.length === 0) {
                vypisChybuHistorie("Zatiaľ žiadne zmeny.");
                return;
            }

            let aktualnyDen = "";
            let ul = null;

            for (let i = 0; i < commity.length; i++) {
                const datum = new Date(commity[i].datum);

                // nový nadpis vždy, keď sa zmení deň
                if (kluc(datum) !== aktualnyDen) {
                    aktualnyDen = kluc(datum);

                    const nadpis = document.createElement("h4");
                    nadpis.className = "git-den";
                    nadpis.textContent = nazovDna(datum);
                    historia.appendChild(nadpis);

                    ul = document.createElement("ul");
                    ul.className = "git-zoznam";
                    historia.appendChild(ul);
                }

                ul.appendChild(vytvorCommit(commity[i]));
            }
        })
        .catch(function () {
            vypisChybuHistorie("Nepodarilo sa načítať históriu zmien.");
        });
}

nacitajHistoriu();

// Board sa číta zo súboru trello.json, ktorý pravidelne aktualizuje GitHub Action.
// V repozitári nie sú žiadne kľúče ani tokeny.
const kontajner = document.getElementById("trello-board");

// zoznamy, ktoré sa na webe nemajú zobrazovať (porovnáva sa začiatok názvu)
const SKRYTE_ZOZNAMY = ["Trello Starter Guide", "Today", "Next Meeting", "Later"];

function vypisChybu(sprava) {
    kontajner.innerHTML = "";
    const p = document.createElement("p");
    p.textContent = sprava;
    kontajner.appendChild(p);
}

function jeSkryty(nazov) {
    return SKRYTE_ZOZNAMY.some(function (skryty) {
        return nazov.startsWith(skryty);
    });
}

function nacitajKarty() {
    fetch("trello.json", { cache: "no-store" })
        .then(function (odpoved) {
            if (!odpoved.ok) {
                throw new Error("trello.json sa nenašiel");
            }
            return odpoved.json();
        })
        .then(function (zoznamy) {
            kontajner.innerHTML = "";

            let zobrazene = 0;

            for (let i = 0; i < zoznamy.length; i++) {
                const karty = zoznamy[i].cards;
                if (jeSkryty(zoznamy[i].name) || karty.length === 0) {
                    continue;
                }
                zobrazene++;

                const stlpec = document.createElement("div");
                stlpec.className = "trello-stlpec";

                const nadpis = document.createElement("h4");
                nadpis.textContent = zoznamy[i].name;

                let hotove = 0;
                for (let j = 0; j < karty.length; j++) {
                    if (karty[j].dueComplete) {
                        hotove++;
                    }
                }
                const pocet = document.createElement("span");
                pocet.className = "trello-pocet";
                pocet.textContent = hotove + " / " + karty.length + " hotové";
                nadpis.appendChild(pocet);
                stlpec.appendChild(nadpis);

                const ul = document.createElement("ul");
                ul.className = "trello-zoznam";
                for (let j = 0; j < karty.length; j++) {
                    const li = document.createElement("li");
                    const nazov = document.createElement("span");
                    nazov.className = "trello-nazov";
                    nazov.textContent = karty[j].name;
                    li.appendChild(nazov);

                    if (karty[j].dueComplete) {
                        li.className = "hotovo";
                    }

                    if (karty[j].due) {
                        const termin = document.createElement("span");
                        termin.className = karty[j].dueComplete ? "trello-termin hotovo" : "trello-termin";
                        termin.textContent = new Date(karty[j].due).toLocaleDateString("sk-SK");
                        li.appendChild(termin);
                    }

                    const odpocet = karty[j].badges;
                    if (odpocet && odpocet.checkItems > 0) {
                        const checklist = document.createElement("span");
                        checklist.className = "trello-checklist";
                        checklist.textContent = odpocet.checkItemsChecked + " / " + odpocet.checkItems + " podúloh";
                        li.appendChild(checklist);
                    }
                    ul.appendChild(li);
                }

                stlpec.appendChild(ul);
                kontajner.appendChild(stlpec);
            }

            if (zobrazene === 0) {
                vypisChybu("Board je prázdny.");
            }
        })
        .catch(function () {
            vypisChybu("Nepodarilo sa načítať Trello.");
        });
}

// prvé načítanie hneď po otvorení stránky
nacitajKarty();

// potom znova každých 5 minút
setInterval(nacitajKarty, 300000);
